// Open an unauthenticated gateway socket for each API version and report the first frame or close code.
const WebSocket = require(process.argv[2]);
for (const v of [6, 7, 10]) {
  const ws = new WebSocket(`wss://gateway.discord.gg/?v=${v}&encoding=json`);
  const t = setTimeout(() => { console.log(`v${v}: no response`); ws.terminate(); }, 8000);
  ws.on('message', d => { const p = JSON.parse(d); console.log(`v${v}: op=${p.op}`, p.op === 10 ? '(HELLO - version accepted)' : JSON.stringify(p).slice(0,120)); clearTimeout(t); ws.close(1000); });
  ws.on('close', (c, r) => { if (c !== 1000 && c !== 1005) console.log(`v${v}: closed ${c} ${r}`); clearTimeout(t); });
  ws.on('error', e => console.log(`v${v}: error ${e.message}`));
}
EOF
